const br = ($input.first().json.br || '').trim().toUpperCase();
const BR_REGEX = /^BR\d{7}$/;

if (!BR_REGEX.test(br)) {
  throw new Error(`BR inválido: "${br}". Formato esperado: BR seguido de 7 dígitos.`);
}

return [{ json: { br } }];

const planoItems = $('BuscarDividasCliente').all();
const respostaPostgres = $('BuscarDividasPostgres').first().json;

if (planoItems.length === 0) {
  throw new Error('Nenhum plano encontrado para esse BR.');
}

const plano = planoItems[0].json;

const cols = (respostaPostgres.data?.cols || []).map(c => c.name);
const rows = respostaPostgres.data?.rows || [];
const dividasPostgres = rows.map(row => {
  const obj = {};
  cols.forEach((nome, i) => { obj[nome] = row[i]; });
  return obj;
});

// --- Nível 2: Snapshot do plano original (settlement_plan.debts) ---
// Congelado no momento em que o plano foi criado. Casa por uid.
let snapshotPorUid = {};
try {
  const debtsRaw = plano.debts_json_raw;
  const debtsArray = typeof debtsRaw === 'string' ? JSON.parse(debtsRaw) : (debtsRaw || []);
  for (const entry of debtsArray) {
    if (entry && entry.id) {
      snapshotPorUid[entry.id] = {
        mes_previsto_quitacao_snapshot: entry.settlement_month ?? null,
        data_estimada_quitacao_snapshot: entry.estimated_settlement_date ?? null,
        payment_to_bank_snapshot: entry.payment_to_bank != null ? Number(entry.payment_to_bank) : null,
        reduction_commission_snapshot: entry.reduction_commission != null ? Number(entry.reduction_commission) : null
      };
    }
  }
} catch (e) {
  snapshotPorUid = {};
}

// --- Nível 3: Snapshot do aditivo mais recente (berex.addendum.new_debts) ---
// Congelado no momento em que o aditivo foi aceito. Cobre dívidas que
// entraram DEPOIS do plano original (por isso não têm snapshot no nível 2).
// Não dá pra casar por uid aqui — o "id" dentro desse JSON não é o mesmo
// uid do credit_repair_debts, e o "old_id" costuma vir 0 pra dívidas
// tratadas como "novas" pelo aditivo. O cruzamento confiável é por
// banco (financial_entity) + valor (current_debt_amount ≈ valor_original).
function limparValorMonetario(str) {
  if (str == null) return null;
  const numerico = String(str).replace(/[^0-9.,]/g, '');
  const semMilhar = numerico.replace(/,/g, '');
  const n = parseFloat(semMilhar);
  return isNaN(n) ? null : n;
}

let aditivoEntries = [];
try {
  const listaEntries = plano.aditivo_new_debts_raw; // já vem como lista "achatada" de objetos
  if (Array.isArray(listaEntries)) {
    for (const entry of listaEntries) {
      if (!entry || typeof entry !== 'object') continue;
      aditivoEntries.push({
        financial_entity: entry.financial_entity != null ? Number(entry.financial_entity) : null,
        valor: limparValorMonetario(entry.current_debt_amount),
        mes_previsto_quitacao_aditivo: entry.settlement_month ?? null,
        data_estimada_quitacao_aditivo: entry.estimated_settlement_date ?? null
      });
    }
  }
} catch (e) {
  aditivoEntries = [];
}

function buscarNoAditivo(bancoId, valorOriginal) {
  if (bancoId == null || valorOriginal == null) return null;
  return aditivoEntries.find(e =>
    e.financial_entity === Number(bancoId) &&
    e.valor != null &&
    Math.abs(e.valor - valorOriginal) < 0.02
  ) || null;
}

function classificarStatus(d) {
  if (['new', 'negotiation'].includes(d.estado_divida_raw)) return 'em_aberto';
  if (d.estado_divida_raw === 'cancelled') return 'cancelada';
  if (d.estado_divida_raw === 'liquidation_structured_payment') return 'estruturada';
  if (d.liquidated_with_structured_payments) return 'estruturada';
  if (d.estado_divida_raw === 'paid') return 'paga';
  if (d.estado_divida_raw == null) return 'desconhecido';
  return 'liquidada';
}

function estimarComissao(valorOriginal, valorPago) {
  if (valorOriginal == null || valorPago == null) return null;
  const economia = valorOriginal - valorPago;
  if (economia <= 0) return 0; // sem economia (ou pagou mais que o original) — sem comissão de êxito
  return Math.round(economia * 100 * 0.175) / 100;
}

// NOVO — tags da dívida (berex.credit_repair_debts.labels).
// O SQL devolve "labels" como texto separado por vírgula e
// "acordo_quebrado" como booleano. Parse defensivo porque o Metabase
// às vezes devolve booleano como string.
function parseLabels(raw) {
  if (raw == null) return [];
  if (Array.isArray(raw)) return raw.map(s => String(s).trim()).filter(Boolean);
  return String(raw).replace(/[{}\[\]"]/g, '').split(',').map(s => s.trim()).filter(Boolean);
}

// --- Cálculo de parcelas pagas, respeitando mudanças de aporte ao longo
// do tempo (aditivos que aumentaram ou diminuíram o valor da parcela) ---
//
// Antes: somava TODOS os depósitos e dividia pelo aporte ATUAL — funciona
// só se o aporte nunca mudou. Se o cliente pagou parte no valor antigo e
// parte no valor novo, isso super ou subestima a contagem.
//
// Agora: monta uma linha do tempo de "qual era o aporte vigente em cada
// período" (original → 1º aditivo → 2º aditivo → ...), e cada depósito é
// convertido em parcelas usando o aporte que valia NA DATA daquele depósito.
function calcularParcelasPagas(plano) {
  const listaDepositos = Array.isArray(plano.lista_depositos_raw) ? plano.lista_depositos_raw : [];
  const timelineAditivos = Array.isArray(plano.timeline_aportes_raw) ? plano.timeline_aportes_raw : [];

  // Sem dados suficientes pra fazer o cálculo certo: reserva antiga
  if (listaDepositos.length === 0 || !plano.aporte_mensal) {
    return Math.max((plano.qtd_depositos_reais || 0) - 1, 0);
  }

  // Lista dos valores de aporte que já existiram (original + cada mudança
  // por aditivo). Não precisa de data aqui — a escolha de qual aporte usar
  // pra cada depósito é feita pelo VALOR, não pela data (ver função abaixo).
  const aportesConhecidos = [plano.aporte_mensal_original ?? plano.aporte_mensal];
  for (const item of timelineAditivos) {
    const aporte = limparValorMonetario(item.aporte_raw);
    if (aporte != null && aporte > 0) aportesConhecidos.push(aporte);
  }

  // Pra cada depósito, escolhe — entre os aportes já usados nesse plano —
  // aquele que faz o valor bater mais perto de um número inteiro de
  // parcelas. Isso é mais confiável que escolher só pela data: às vezes um
  // depósito acontece DEPOIS da data do aditivo mas ainda no valor antigo
  // (atraso de um ciclo de cobrança), e escolher por data classificaria
  // errado, inflando a conta.
  function parcelasDoDeposito(valor) {
    let melhorAporte = aportesConhecidos[0];
    let menorResto = Infinity;
    for (const aporte of aportesConhecidos) {
      const parcelas = valor / aporte;
      const resto = Math.abs(parcelas - Math.round(parcelas));
      if (resto < menorResto) {
        menorResto = resto;
        melhorAporte = aporte;
      }
    }
    return valor / melhorAporte;
  }

  // O primeiro depósito (cronologicamente) é SEMPRE a taxa de ativação do
  // cliente — nunca conta como parcela, não importa o valor dele. Regra
  // confirmada com o time.
  let totalParcelas = 0;
  listaDepositos.forEach((dep, i) => {
    if (i === 0) return; // pula a entrada
    totalParcelas += parcelasDoDeposito(Number(dep.valor));
  });

  return Math.floor(totalParcelas);
}

const dividas = dividasPostgres.map(d => {
  const snapshot = snapshotPorUid[d.debt_uid] || null;

  // Comissão PROJETADA associada ao valor inicial (plano): sempre estimada
  // em cima da economia total esperada (dívida - pagamento inicial) * 17,5%.
  // Não usa a comissão real do Postgres aqui — ela reflete outra coisa
  // (comissão já realizada até agora), não a comissão projetada do plano
  // inteiro. Confirmado batendo exato com a tela do Berex: (86.679,86 -
  // 8.667,99) * 0,175 + 8.667,99 = 22.320,07.
  const comissaoParaPlano = estimarComissao(d.valor_original, d.valor_pago_banco_inicial);

  // Prioridade: valor CADASTRADO no plano de liquidação (payment_to_bank +
  // reduction_commission, congelados na época em que o plano foi criado).
  // Só cai pro cálculo estimado se essa dívida não tiver snapshot no plano
  // (ex: entrou depois via aditivo, ou o tracker_id não bate com nenhum lead).
  const pagoTotalPadrao = (snapshot && snapshot.payment_to_bank_snapshot != null)
    ? Math.round((snapshot.payment_to_bank_snapshot + (snapshot.reduction_commission_snapshot || 0)) * 100) / 100
    : (d.valor_pago_banco_inicial != null
        ? Math.round((d.valor_pago_banco_inicial + (comissaoParaPlano || 0)) * 100) / 100
        : null);

  const houveMudanca = d.valor_pago_banco_inicial != null && d.valor_pago_banco_atual != null
    && Math.abs(d.valor_pago_banco_inicial - d.valor_pago_banco_atual) > 0.01;
   const comissaoAtualizada = houveMudanca
    ? estimarComissao(d.valor_original, d.valor_pago_banco_atual)
    : null;
  const pagoTotalAtualizacao = houveMudanca
    ? Math.round((d.valor_pago_banco_atual + (comissaoAtualizada || 0)) * 100) / 100
    : null;

  // --- Cadeia de fallback pra mes_previsto_quitacao: ao vivo → snapshot do
  // ADITIVO (mais recente, se existir) → snapshot do plano original ---
  // Importante: o aditivo vem ANTES do plano no fallback, porque ele é mais
  // recente — se um aditivo atualizou o prazo dessa dívida, essa atualização
  // tem que vencer a previsão antiga do plano original.
  let mesPrevistoFinal = null;
  let origemMesPrevisto = null;
  let dataEstimadaFinal = null;

  if (d.mes_previsto_quitacao != null) {
    mesPrevistoFinal = d.mes_previsto_quitacao;
    origemMesPrevisto = 'live';
  } else {
    const matchAditivo = buscarNoAditivo(d.banco_id, d.valor_original);
    if (matchAditivo && matchAditivo.mes_previsto_quitacao_aditivo != null) {
      mesPrevistoFinal = matchAditivo.mes_previsto_quitacao_aditivo;
      origemMesPrevisto = 'snapshot_aditivo';
      dataEstimadaFinal = matchAditivo.data_estimada_quitacao_aditivo ?? null;
    } else if (snapshot && snapshot.mes_previsto_quitacao_snapshot != null) {
      mesPrevistoFinal = snapshot.mes_previsto_quitacao_snapshot;
      origemMesPrevisto = 'snapshot_plano';
      dataEstimadaFinal = snapshot.data_estimada_quitacao_snapshot ?? null;
    }
  }

  // Desconto real: usa o "pago total atualização" (que já inclui a comissão)
  // quando ele existir — antes usava o valor bruto sem comissão, o que não
  // batia com o R$ mostrado no card como "Pago total atualização"
  const baseParaDesconto = pagoTotalAtualizacao != null ? pagoTotalAtualizacao : pagoTotalPadrao;

  // Parcelas do pagamento estruturado (só existe pra dívidas nesse regime).
  // O Postgres já devolve como JSON via json_agg; parse defensivo caso
  // venha como string em vez de objeto já parseado.
  let parcelasEstruturado = null;
  if (d.parcelas_estruturado_raw) {
    try {
      parcelasEstruturado = typeof d.parcelas_estruturado_raw === 'string'
        ? JSON.parse(d.parcelas_estruturado_raw)
        : d.parcelas_estruturado_raw;
    } catch (e) {
      parcelasEstruturado = null;
    }
  }

  // NOVO — tags e flag de acordo quebrado
  const labels = parseLabels(d.labels);
  const acordoQuebrado = d.acordo_quebrado === true
    || d.acordo_quebrado === 'true'
    || labels.includes('broken_agreement');

  return {
    banco: d.banco,
    banco_id: d.banco_id,
    numero_contrato: d.numero_contrato,
    valor_original: d.valor_original,
    valor_pago_banco: d.valor_pago_banco_atual,
    desconto_atual: d.valor_original && baseParaDesconto != null ? Math.round((1 - baseParaDesconto / d.valor_original) * 10000) / 10000 : null,
    comissao_sucesso: d.comissao_sucesso,
    pago_total_padrao: pagoTotalPadrao,
    pago_total_atualizacao: pagoTotalAtualizacao,
    current_balance_postgres: d.current_balance,
    estado_divida_raw: d.estado_divida_raw,
    status_divida: classificarStatus(d),
    liquidado_com_credito: Boolean(d.liquidated_with_credit),
    data_ultima_atualizacao_divida: d.data_ultima_atualizacao_divida,
    mes_previsto_quitacao: mesPrevistoFinal,
    mes_previsto_quitacao_origem: origemMesPrevisto,
    data_estimada_quitacao_snapshot: dataEstimadaFinal,
    parcelas_estruturado: parcelasEstruturado,
    acordo_quebrado: acordoQuebrado, // NOVO
    labels: labels                   // NOVO
  };
});

// --- Ordenação: dívidas em aberto aparecem primeiro ---
const prioridadeStatus = {
  em_aberto: 0,
  desconhecido: 1,
  estruturado: 2,
  estruturada: 3,
  paga: 4,
  liquidada: 5,
  cancelada: 6
};

dividas.sort((a, b) => {
  const pa = prioridadeStatus[a.status_divida] ?? 99;
  const pb = prioridadeStatus[b.status_divida] ?? 99;
  return pa - pb;
});

const resultadoParcelas = calcularParcelasPagas(plano);

return [{
  json: {
    br: plano.br,
    nome_cliente: plano.nome_cliente,
    status_berex: plano.status_berex,
    sub_state: plano.sub_state,
    data_inicio: plano.data_inicio,
    mes_do_plano: plano.mes_do_plano,
    duracao_programa: plano.duracao_programa,
    divida_total: plano.divida_total,
    aporte_mensal: plano.aporte_mensal,
    qtd_dividas: dividas.length,
    // Sem aditivo, mes_do_plano já não conta o mês de ativação → parcelas esperadas = mês do plano.
    // Com aditivo, mantém a regra anterior (mês do aditivo conta como mês 1).
    parcelas_esperadas: plano.teve_aditivo
      ? Math.max((plano.mes_do_plano || 0) - 1, 0)
      : Math.max(plano.mes_do_plano || 0, 0),
    parcelas_pagas: resultadoParcelas,
    teve_aditivo: plano.teve_aditivo,
    data_aditivo: plano.data_aditivo,
    data_ultima_atualizacao_plano: plano.data_ultima_atualizacao_plano,
    atualizado_ultimos_45_dias: plano.atualizado_ultimos_45_dias,
    ultima_atualizacao_dividas: plano.ultima_atualizacao_dividas,
    poupanca_total: plano.poupanca_total,
    pago_total: plano.pago_total,
    pago_banco_total_plano: plano.pago_banco_total_plano,
    desconto_total_plano: plano.desconto_total_plano,
    dividas: dividas
  }
}];

// ============================================================
// Node: "Curva de Desconto — Lookup + Diff"
// Objetivo: comparar o desconto atual de cada dívida com o
// desconto projetado pela curva (banco + mês do plano), sem
// depender de query pesada nem de o LLM fazer a conta.
// Entrada esperada (item anterior no fluxo, ex: query de dívidas):
//   { cpf, mes_do_plano, dividas: [ { banco, desconto_atual }, ... ] }
// Saída: pacote pequeno e pronto pra ir direto no prompt do LLM.
// ============================================================

// Curva ILUSTRATIVA (os valores reais por credor são dados internos e foram removidos).
// Formato: { "<CREDOR>": [desconto esperado no mês 1, mês 2, ..., mês 60] }
const CURVA_DESCONTO = {"OUTROS": [0.1, 0.12, 0.14, 0.16, 0.18, 0.2, 0.22, 0.24, 0.26, 0.28, 0.3, 0.32, 0.34, 0.36, 0.38, 0.4, 0.42, 0.44, 0.46, 0.48, 0.5, 0.52, 0.54, 0.56, 0.58, 0.6, 0.62, 0.64, 0.66, 0.68, 0.7, 0.72, 0.74, 0.76, 0.78, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8]};

function normalizarBanco(nome) {
  return (nome || "").trim().toUpperCase();
}

// Índice normalizado pra tolerar variações de grafia (ITAÚ vs Itau vs itaú)
const CURVA_INDEX = Object.fromEntries(
  Object.entries(CURVA_DESCONTO).map(([banco, valores]) => [normalizarBanco(banco), valores])
);

function buscarProjetado(banco, mesDoPlano) {
  const chave = normalizarBanco(banco);
  const valores = CURVA_INDEX[chave] || CURVA_INDEX["OUTROS"];
  if (!valores) return null;
  const mes = Math.min(Math.max(mesDoPlano, 1), 60); // cap 1..60
  return valores[mes - 1];
}

const STATUS_DIVIDA_LABEL = {
  em_aberto: 'em aberto',
  paga: 'paga',
  liquidada: 'liquidada',
  liquidada_por_credito: 'liquidada por crédito',
  estruturada: 'estruturada',
  desconhecido: 'com estado desconhecido'
};

function gerarComparacaoTexto(status, tendenciaCurva, projetado, atual) {
  if (status === 'sem_curva') return 'Sem curva de referência para esse credor.';
  if (status === 'abaixo_do_esperado') return 'Desconto atual abaixo do projetado para o mês.';
  if (status === 'acima_do_esperado') return 'Desconto atual acima do projetado para o mês.';
  return 'Desconto dentro do projetado para o mês.';
}

function gerarNotaFinal(statusDivida, prazoStatus) {
  if (statusDivida !== 'em_aberto') {
    return `Dívida já ${STATUS_DIVIDA_LABEL[statusDivida] || statusDivida}.`;
  }
  if (prazoStatus === 'atrasado') return 'Atenção: o prazo de quitação combinado já passou.';
  return 'Dentro do prazo e da margem esperada da curva.';
}

const input = $input.first().json;
const mesDoPlano = input.mes_do_plano;

// Data base do programa (mesma regra usada no BigQuery pra calcular mes_do_plano):
// usa a data do aditivo se teve, senão a data de início do plano.
const dataBaseProgramaStr = (input.teve_aditivo && input.data_aditivo)
  ? input.data_aditivo
  : input.data_inicio;

// Diferença em meses de calendário entre duas datas (equivalente ao
// DATE_DIFF(..., MONTH) do BigQuery — ignora o dia, só conta virada de mês/ano)
function diffMesesCalendario(dataFimStr, dataInicioStr) {
  if (!dataFimStr || !dataInicioStr) return null;
  const fim = new Date(dataFimStr);
  const inicio = new Date(dataInicioStr);
  if (isNaN(fim) || isNaN(inicio)) return null;
  return (fim.getFullYear() - inicio.getFullYear()) * 12 + (fim.getMonth() - inicio.getMonth());
}

// Texto resumido pro topo do card, só pra dívidas já pagas (e equivalentes:
// liquidada / liquidada_por_credito, que contam como a mesma coisa)
function gerarStatusResumoPago(prazoStatus, diffPP) {
  // Só esconde de verdade se não tiver NENHUM dos dois dados
  if (prazoStatus == null && diffPP == null) return null;

  let descontoTexto = 'dentro do esperado';
  if (diffPP != null) {
    if (diffPP > 3) descontoTexto = `${diffPP} p.p. acima do esperado`;
    else if (diffPP < -3) descontoTexto = `${Math.abs(diffPP)} p.p. abaixo do esperado`;
  }

  // Sem prazo previsto (ex: dívida entrou via aditivo, nunca teve
  // settlement_month registrado) — mostra só o desconto
  if (prazoStatus == null) {
    return `Quitada com desconto ${descontoTexto}`;
  }

  const prazoTexto = prazoStatus === 'no_prazo'
    ? 'dentro do prazo previsto'
    : 'após o prazo previsto';

  return `Quitada ${prazoTexto} · desconto ${descontoTexto}`;
}

const dividasComparadas = (input.dividas || []).map(d => {
  // "paga", "liquidada" e "liquidada_por_credito" contam como a mesma coisa
  // pra fins de travar o mês na quitação e calcular o resumo de status
  const dividaJaPaga = d.status_divida === 'paga'
    || d.status_divida === 'liquidada'
    || d.status_divida === 'liquidada_por_credito';

  // Pra dívida já paga/liquidada: trava o "mês" no momento da quitação (não
  // no mês atual do cliente, que continua subindo mesmo depois que a dívida
  // já foi resolvida). Pras demais: mantém o comportamento original.
  let mesParaCurva;
  if (dividaJaPaga && d.data_ultima_atualizacao_divida && dataBaseProgramaStr) {
    // Mesma regra do BigQuery: sem aditivo, o mês de entrada (ativação) não conta.
    const ajusteMes = (input.teve_aditivo && input.data_aditivo) ? 1 : 0;
    const mesCalculado = diffMesesCalendario(d.data_ultima_atualizacao_divida, dataBaseProgramaStr) + ajusteMes;
    mesParaCurva = Math.min(Math.max(mesCalculado, 1), 60);
  } else {
    mesParaCurva = d.mes_da_divida || mesDoPlano;
  }

  const chave = normalizarBanco(d.banco);
  const valores = CURVA_INDEX[chave] || CURVA_INDEX["OUTROS"];
  const projetado = buscarProjetado(d.banco, mesParaCurva);
  const atual = d.desconto_atual;
  const diffPP = projetado != null ? Math.round((atual - projetado) * 1000) / 10 : null;

  let tendenciaCurva = "estavel";
  if (valores) {
    const mesAtualIdx = Math.min(Math.max(mesParaCurva, 1), 60) - 1;
    const proximosMeses = valores.slice(mesAtualIdx, Math.min(mesAtualIdx + 6, 60));
    if (proximosMeses.some(v => v > valores[mesAtualIdx] + 0.02)) {
      tendenciaCurva = "subindo";
    }
  }

  const prazoPrevisto = d.mes_previsto_quitacao;
  const prazoStatus = prazoPrevisto == null ? null
    : mesParaCurva <= prazoPrevisto ? "no_prazo"
    : "atrasado";
  const mesesParaPrazo = prazoPrevisto != null ? prazoPrevisto - mesParaCurva : null;

  // Se o pago total atualização (com comissão) ficou MAIOR que o pago total
  // plano, isso é ruim de verdade — não importa o que a curva diga, não pode
  // aparecer como "acima do esperado"
  const piorouVsPlano = d.pago_total_atualizacao != null && d.pago_total_padrao != null
    && d.pago_total_atualizacao > d.pago_total_padrao;

  const status = piorouVsPlano ? "abaixo_do_esperado"
