const raw = $input.first().json.text;

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  throw new Error('LLM não retornou JSON válido: ' + raw);
}

return [{ json: parsed }];

const dadosEstruturados = $('CurvadeDesconto').first().json;
const llmOutput = $input.first().json;

function paraNumero(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return isNaN(n) ? null : n;
}

function paraBooleano(v) {
  return v === true || v === 'true';
}

// NOVO — tags vêm direto do AgruparDividas (o CurvadeDesconto não repassa).
// Casa por banco + valor_original, que é único por dívida na prática.
const tagsPorDivida = {};
for (const dv of ($('AgruparDividas').first().json.dividas || [])) {
  const chave = `${dv.banco}|${Number(dv.valor_original).toFixed(2)}`;
  tagsPorDivida[chave] = {
    acordo_quebrado: paraBooleano(dv.acordo_quebrado),
    labels: Array.isArray(dv.labels) ? dv.labels : []
  };
}
function buscarTags(d) {
  const chave = `${d.banco}|${Number(d.valor_original).toFixed(2)}`;
  return tagsPorDivida[chave] || { acordo_quebrado: false, labels: [] };
}

return [{
  json: {
    br: dadosEstruturados.br,
    nome_cliente: dadosEstruturados.nome_cliente,
    status_berex: dadosEstruturados.status_berex,
