    teve_aditivo: paraBooleano(dadosEstruturados.teve_aditivo),
    data_aditivo: dadosEstruturados.data_aditivo,
    data_ultima_atualizacao_plano: dadosEstruturados.data_ultima_atualizacao_plano,
    atualizado_ultimos_45_dias: paraBooleano(dadosEstruturados.atualizado_ultimos_45_dias),
    ultima_atualizacao_dividas: dadosEstruturados.ultima_atualizacao_dividas,
    poupanca_total: paraNumero(dadosEstruturados.poupanca_total),
    pago_total: paraNumero(dadosEstruturados.pago_total),
    pago_banco_total_plano: paraNumero(dadosEstruturados.pago_banco_total_plano),
    desconto_total_plano: paraNumero(dadosEstruturados.desconto_total_plano),
    dividas: (dadosEstruturados.dividas || []).map(d => {
      const tags = buscarTags(d); // NOVO
      return {
        banco: d.banco,
        desconto_atual: paraNumero(d.desconto_atual),
        desconto_projetado: paraNumero(d.desconto_projetado),
        diff_pp: paraNumero(d.diff_pp),
        valor_original: paraNumero(d.valor_original),
        pago_banco_plano: paraNumero(d.pago_banco_plano),
