const crypto = require('crypto');

const SECRET = $env.SESSION_SECRET; // mesma chave do GerarSessao

const bodyRecebido = $('Webhook').first().json.body;
const tokenRecebido = bodyRecebido?.session_token || '';
const emailEsperado = (bodyRecebido?.session_email || '').trim().toLowerCase();

const partes = tokenRecebido.split('.');

if (partes.length !== 2) {
  return [{ json: { sessao_valida: false, erro: 'Sessão inválida. Faça login novamente.' } }];
}

const [payload, assinatura] = partes;
const assinaturaEsperada = crypto.createHmac('sha256', SECRET).update(payload).digest('hex');

if (assinatura !== assinaturaEsperada) {
  return [{ json: { sessao_valida: false, erro: 'Sessão inválida. Faça login novamente.' } }];
}

const decodificado = Buffer.from(payload, 'base64').toString('utf8');
const [emailNoToken, expiraEmStr] = decodificado.split('|');

if (Number(expiraEmStr) < Date.now()) {
  return [{ json: { sessao_valida: false, erro: 'Sessão expirada. Faça login novamente.' } }];
}

if (emailNoToken !== emailEsperado) {
  return [{ json: { sessao_valida: false, erro: 'Sessão inválida. Faça login novamente.' } }];
}

// Sessão ok — repassa o BR (e o e-mail do operador, se quiser usar em logs no futuro)
return [{ json: { sessao_valida: true, br: bodyRecebido.br, operador_email: emailNoToken } }];
